export default {
  async fetch(request) {
    const url = new URL(request.url);
    
    // Extract everything after the worker origin to get the target proxy URL
    const targetUrl = url.href.substring(url.origin.length + 1);
    if (!targetUrl) {
      return new Response("Missing target URL", { status: 400 });
    }

    // Read the new standardized, consistent operational headers
    const forceCache = request.headers.get("X-Proxy-Force-Cache") === "true";
    const ttl = parseInt(request.headers.get("X-Proxy-Cache-TTL"), 10) || 31536000;
    const isRangeRequest = request.headers.has("Range");

    // Clone headers to safely modify them
    const headers = new Headers(request.headers);
    
    // Automatically sanitize and strip all custom proxy configuration headers 
    headers.delete("X-Proxy-Force-Cache");
    headers.delete("X-Proxy-Cache-TTL");

    // Dynamic Cloudflare Edge cache configuration
    const cfOptions = {};
    if (forceCache) {
      cfOptions.cacheEverything = true;
      cfOptions.cacheTtlByStatus = {
        "200-299": isRangeRequest ? -1 : ttl,
        "404": -1,
        "500-599": -1
      };
    }

    const modifiedRequest = new Request(targetUrl, {
      method: request.method,
      headers,
      body: !["GET", "HEAD"].includes(request.method) ? request.body : null,
      redirect: "follow",
      cf: cfOptions
    });

    const response = await fetch(modifiedRequest);

    // Standardized Browser/Client header overrides
    if (response.ok && request.method === "GET" && forceCache) {
      // FIX: Instead of wrapping response.body (which breaks streams/ranges on first-load),
      // create a new Response using the exact original response object to preserve the pipe,
      // but supply your modified headers.
      const newHeaders = new Headers(response.headers);
      
      if (isRangeRequest || ttl < 1) {
        newHeaders.set("Cache-Control", "no-store");
      } else {
        newHeaders.set("Cache-Control", `public, max-age=${ttl}, immutable`);
      }

      // Return a fresh response wrapper using the original response entity
      // This preserves internal stream plumbing for tools like wget
      return new Response(response.body, {
        status: response.status,
        statusText: response.statusText,
        headers: newHeaders
      });
    }

    return response;
  }
};
